import "../styles/globals.css";
import { useEffect } from "react";
import Head from "next/head";
import { ClockProvider, CommercialProvider, PageProvider, ThemeProvider } from "../components/contexts.jsx";
import { NOW } from "../lib/clock.js";
import { startTracker } from "../integration/tracker.js";
import { registerCommercialSlots } from "../integration/commercial.js";

export default function PortalApp({ Component, pageProps }) {
    const { page } = pageProps;
    useEffect(() => {
        if (!page)
            return;
        const stopTracker = startTracker();
        // The page is loaded once it has hydrated, its fonts are there and
        // its ads are on it.
        Promise.all([registerCommercialSlots(page.thirdParty), window.__portalFonts]).then(() => window.__portal.signal("page-ready", { pageType: page.pageType }));
        window.__portal.signal("page-hydrated", { pageType: page.pageType });
        return stopTracker;
    }, [page]);
    if (!page)
        return <Component {...pageProps} />;
    return (
        <PageProvider page={page}>
            <ClockProvider now={NOW}>
                <ThemeProvider theme="light">
                    <CommercialProvider config={page.thirdParty}>
                        <Head>
                            <title>{`${page.title} | ${page.siteName}`}</title>
                            <meta name="viewport" content="width=device-width, initial-scale=1" />
                        </Head>
                        <Component {...pageProps} />
                    </CommercialProvider>
                </ThemeProvider>
            </ClockProvider>
        </PageProvider>
    );
}
