// Hands the page's ad slots to the ad tag once the page has hydrated, and
// resolves once the ad server has rendered every slot that isn't lazy, from
// its slotRenderEnded events. Lazy slots render when they come near the
// viewport, so a page load doesn't wait for them.
export function registerCommercialSlots(config) {
    if (!config?.adtag)
        return Promise.resolve();
    const elements = [...document.querySelectorAll("[data-commercial-slot]")];
    const slots = elements.map((element) => element.dataset.commercialSlot);
    const waiting = new Set(elements.filter((element) => element.dataset.commercialLazy !== "true").map((element) => element.id));
    const rendered = new Promise((resolve) => {
        if (!waiting.size)
            resolve();
        window.adserver = window.adserver || { cmd: [] };
        window.adserver.cmd.push(() => {
            window.adserver.pubads().addEventListener("slotRenderEnded", (event) => {
                if (waiting.delete(event.slot.getSlotElementId()) && !waiting.size)
                    resolve();
            });
        });
    });
    window.adtag = window.adtag || { cmd: [] };
    window.adtag.cmd.push(() => {
        window.adtag.configure(config.adtag);
        window.adtag.registerSlots(slots);
        window.adtag.start();
    });
    return rendered;
}
